package com.kasa.diagnostic;
import android.app.*;import android.os.*;import android.content.*;import android.graphics.Color;import android.hardware.usb.UsbManager;import android.provider.Settings;import android.view.*;import android.widget.*;
public class MainActivity extends Activity {
 LinearLayout root; TextView report; String lastReport=""; int bg=0xff0c0c0f, red=0xffbc1828;
 public void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(bg);getWindow().setNavigationBarColor(bg);ScrollView sc=new ScrollView(this);root=new LinearLayout(this);root.setOrientation(1);root.setPadding(28,36,28,36);root.setBackgroundColor(bg);sc.addView(root);setContentView(sc);
 label("KasA",30,red);label("SETTINGS DIAGNOSTIC • 0.1",14,Color.LTGRAY);label("USB / OEM inspection",22,Color.WHITE);label("Read-only checks. Android and Samsung restrictions still apply.",14,Color.LTGRAY);
 button("Run USB diagnostics",()->diagnose());button("USB preferences",()->open("android.settings.USB_SETTINGS"));button("Developer options",()->open(Settings.ACTION_APPLICATION_DEVELOPMENT_SETTINGS));button("OEM unlocking information",()->oem());button("Device administrators",()->open(Settings.ACTION_DEVICE_ADMIN_SETTINGS));button("General settings",()->open(Settings.ACTION_SETTINGS));button("Copy diagnostic report",()->{((android.content.ClipboardManager)getSystemService(CLIPBOARD_SERVICE)).setPrimaryClip(ClipData.newPlainText("KasA diagnostics",lastReport));Toast.makeText(this,"Copied",Toast.LENGTH_SHORT).show();});report=label("Run diagnostics to inspect available USB signals.",14,Color.WHITE);
 }
 TextView label(String s,int size,int color){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(color);t.setPadding(0,10,0,12);root.addView(t);return t;}
 void button(String s,Runnable r){Button b=new Button(this);b.setText(s);b.setAllCaps(false);b.setTextColor(Color.WHITE);b.setBackgroundTintList(android.content.res.ColorStateList.valueOf(red));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,6,0,6);root.addView(b,p);b.setOnClickListener(v->r.run());}
 void open(String action){try{startActivity(new Intent(action));}catch(Exception e){new AlertDialog.Builder(this).setMessage("Screen unavailable or restricted on this device.").setPositiveButton("OK",null).show();}}
 void oem(){String state="OEM unlock status is not exposed by a reliable public Android API.";try{android.os.UserManager um=(android.os.UserManager)getSystemService(USER_SERVICE);if(um!=null&&um.hasUserRestriction(android.os.UserManager.DISALLOW_FACTORY_RESET))state+=" Factory reset restricted by policy.";}catch(Exception ignored){}new AlertDialog.Builder(this).setTitle("OEM Unlocking").setMessage(state+" Check Developer Options. This app cannot bypass Samsung or carrier restrictions.").setNegativeButton("Close",null).setPositiveButton("Developer Options",(d,w)->open(Settings.ACTION_APPLICATION_DEVELOPMENT_SETTINGS)).show();}
 void diagnose(){StringBuilder s=new StringBuilder("KasA Settings Diagnostic v0.1\n");s.append("Device: ").append(Build.MANUFACTURER).append(" ").append(Build.MODEL).append("\nAndroid: ").append(Build.VERSION.RELEASE).append("\n");UsbManager u=(UsbManager)getSystemService(USB_SERVICE);if(u==null)s.append("USB service unavailable\n");else{try{s.append("USB host devices visible: ").append(u.getDeviceList().size()).append("\n");}catch(Exception e){s.append("USB host inspection unavailable\n");}}try{s.append("ADB setting: ").append(Settings.Global.getInt(getContentResolver(),Settings.Global.ADB_ENABLED,0)==1?"ON":"OFF").append("\n");}catch(Exception e){s.append("ADB state unreadable\n");}s.append("OEM state: unavailable through public API\nUSB host count does not indicate PC connection.\nFlickering can involve cable, port, negotiation, system UI, or policy. This scan alone cannot identify the cause.");lastReport=s.toString();report.setText(lastReport);}
}